from starlette._utils import is_async_callable
from typing import Callable, Union, Awaitable, Response
import functools
import inspect

def _is_async_callable_deep(func: Callable) -> bool:
    """
    Checks if a callable is an async function, even if wrapped by partial or decorators.
    """
    while True:
        try:
            # Unwrap decorators
            func = inspect.unwrap(func)
        except TypeError:
            # Not a standard function/method, might be a class instance or something else
            pass

        if isinstance(func, functools.partial):
            func = func.func

        # Check if the unwrapped function is a coroutine function
        if inspect.iscoroutinefunction(func):
            return True

        # If it's not a function, we stop unwrapping to avoid infinite loops
        if not callable(func):
            break

    return False

def request_response(
    func: Callable[[Request], Union[Awaitable[Response], Response]],
) -> ASGIApp:
    """
    Takes a function or coroutine `func(request) -> response`,
    and returns an ASGI application.
    """
    f: Callable[[Request], Awaitable[Response]] = (
        func if _is_async_callable_deep(func) else functools.partial(run_in_threadpool, func)  # type:ignore
    )

